using System.Diagnostics.CodeAnalysis;
using Fdw.Collections;
using Fdw.Services.Abstractions;
using Fdw.Services.Abstractions.Health.Monitoring;
using Fdw.ServiceTypes;
using Fdw.ServiceTypes.Logging;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Logging.Abstractions;
using System;

namespace Fdw.Services.HealthChecks.Monitoring;

/// <summary>
/// ServiceTypeCollection for health monitor service types.
/// Generated by ServiceTypeCollectionGenerator with high-performance lookups.
/// </summary>
/// <remarks>
/// <para>
/// The health monitor is a full service domain: options ("Local" in this assembly, "HttpClient" in
/// <c>Fdw.Web.Analytics.Clients</c>) register factories with the domain provider, and consumers depend
/// on the provider (<see cref="IFdwServiceProvider{TService,TConfiguration}"/> of
/// <see cref="IHealthMonitorService"/>/<see cref="HealthMonitorConfiguration"/>) — never on a direct
/// <see cref="IHealthMonitorService"/> registration. Which implementation a host runs is that host's
/// <c>HealthMonitors</c> appsettings row (<c>ServiceOptionType</c>), resolved at first use — not a
/// registration-order race.
/// </para>
/// <para>
/// Cross-assembly options are registered via the <c>[ModuleInitializer]</c> generated by
/// <c>Fdw.Registration.SourceGenerators</c> in the entry-point project.
/// </para>
/// </remarks>
[ExcludeFromCodeCoverage]
[ServiceTypeCollection(
    typeof(HealthMonitorTypeBase<IHealthMonitorService, IHealthMonitorFactory<IHealthMonitorService, HealthMonitorConfiguration>, HealthMonitorConfiguration>),
    typeof(IHealthMonitorType),
    typeof(HealthMonitorTypes),
    GenerateProvider = true,
    ServiceInterface = typeof(IHealthMonitorService),
    ConfigurationType = typeof(HealthMonitorConfiguration),
    // Why: the concrete domain provider + domain-named interface, exactly like ConnectionTypes
    // (DefaultConnectionProvider/IConnectionProvider) — consumers inject IHealthMonitorProvider,
    // so the generated Register must bind THAT interface, not the generic IFdwServiceProvider<,>.
    ProviderType = typeof(DefaultHealthMonitorProvider),
    ProviderInterface = typeof(IHealthMonitorProvider),
    ServiceCategory = "HealthMonitor")]
public partial class HealthMonitorTypes : ServiceTypeCollectionBase<
    HealthMonitorTypeBase<IHealthMonitorService, IHealthMonitorFactory<IHealthMonitorService, HealthMonitorConfiguration>, HealthMonitorConfiguration>,
    IHealthMonitorType>
{

    /// <summary>
    /// Sets this collection's Register body: the option sweep, then this domain's provider.
    /// </summary>
    /// <remarks>
    /// The provider is one registration for the whole collection and this declaration already names it,
    /// so the body that registers it is written here beside the declaration. Setting it as the phase's
    /// body is what makes it replaceable: an application calling <c>Registration(...)</c> replaces the
    /// sweep and this registration together, which is the correct semantic for a host taking over phase 2.
    /// </remarks>
    static HealthMonitorTypes()
    {
        var sweepOptions = RegisterFunc;
        Registration((builder, loggerFactory) =>
        {
            sweepOptions(builder, loggerFactory);
            builder.Services.AddScoped<IHealthMonitorProvider>(sp =>
            {
                var provider = new DefaultHealthMonitorProvider(
                    sp,
                    sp.GetService<ILoggerFactory>()?.CreateLogger<DefaultHealthMonitorProvider>()
                    ?? NullLogger<DefaultHealthMonitorProvider>.Instance);
                var stLogger = sp.GetService<ILoggerFactory>()?.CreateLogger("HealthMonitorTypes");
                try
                {
                    if (sp.GetService<IServiceConfigurationProvider<HealthMonitorConfiguration>>() is { } cfgProvider)
                    {
                        // Why the result is read: a provider that did not take its parent still constructs, and
                        // every later read silently misses. The failure has to be said out loud here or nowhere.
                        var parentResult = provider.Register(cfgProvider);
                        if (!parentResult.IsSuccess && stLogger != null)
                            ServiceTypeLog.FactoryRegistrationFailed(stLogger, "HealthMonitorTypes", parentResult.CurrentMessage ?? "HealthMonitorTypes");
                    }
                }
                catch (Exception ex)
                {
                    // Why rethrow: a throw here was previously silent, and a provider that failed to take
                    // its parent is unusable in a way that only surfaces much later.
                    if (stLogger != null) ServiceTypeLog.FactoryRegistrationException(stLogger, ex, "HealthMonitorTypes");
                    throw;
                }
                return provider;
            });
            return builder;
        });
    }
}
